package com.edu.unal.directorio.data.db

import androidx.room3.Entity
import androidx.room3.Index
import androidx.room3.PrimaryKey

/**
 * Row of the `classification` catalog (design D3): exactly three fixed rows loaded by the
 * creation callback from the `Classification` enum (`id` and `code` come from there).
 *
 * [id] is not autogenerated. [code] is unique and is the only text stored; the Spanish labels
 * come from string resources.
 */
@Entity(
    tableName = "classification",
    indices = [Index(value = ["code"], unique = true)],
)
data class ClassificationEntity(
    @PrimaryKey val id: Int,
    val code: String,
)
